// Replace source_url with your long-form video; settings mirror theharis.ai's options.
return [{ json: {
  source_url: 'https://www.youtube.com/watch?v=EXAMPLE1234',
  provider: 'snazzo.app',
  clip_count: 6,
  clip_length_sec: 45,
  captions: 'karaoke-bold',
  branding: 'lower-third @yourhandle',
  background_music: 'subtle-lofi'
} }];

const j = $input.first().json;
const e = [];
try { const u = new URL(j.source_url); if (!/^https?:$/.test(u.protocol)) e.push('source_url must be http(s)'); } catch { e.push('source_url must be a valid URL'); }
if (!Number.isInteger(j.clip_count) || j.clip_count < 1 || j.clip_count > 50) e.push('clip_count must be 1-50');
if (!Number.isFinite(j.clip_length_sec) || j.clip_length_sec < 5 || j.clip_length_sec > 180) e.push('clip_length_sec must be 5-180');
if (!['snazzo.app','theharis.tool','cardio'].includes((j.provider||'').toLowerCase().replace(/\s+/g,''))) {
  // allow any string but flag unknown named providers explicitly
}
if (e.length) throw new Error('Invalid input: ' + e.join('; '));
return [{ json: j }];

const j = $input.first().json;
const crypto = require('crypto');
const job_id = crypto.createHash('sha1').update(j.source_url + '|' + j.provider + '|' + j.clip_count).digest('hex').slice(0, 12);
return [{ json: {
  job_id,
  status: 'awaiting_operator',
  provider: j.provider,
  source_url: j.source_url,
  operator_steps: [
    'Open ' + j.provider + ' and paste: ' + j.source_url,
    'Request ' + j.clip_count + ' clips at ~' + j.clip_length_sec + 's each',
    'Captions: ' + j.captions + '; Branding: ' + j.branding + '; Music: ' + j.background_music,
    'Download the produced clips and record their file paths / URLs against job_id ' + job_id
  ],
  clip_generation: 'PENDING: no verified API for ' + j.provider + '. Use the user-stack OpenShorts variant for an automated clipper.',
  posting: 'DRAFT/APPROVAL ONLY: no auto-post is implemented.'
} }];
